window.docContents[46].resolve({"/rules/RG1007/#RG1007-proof-shape":{"contents":"ExecutableContract f R for a named constant f with R : type-of-f → Prop stating the full-domain requirement. The proof inhabits exactly R f; a weaker R changes the requirement and is a review failure.\n\n","context":"Regula rule reference\u0009Rule index\u0009RG1007: Executable contracts require supported closed evidence","header":"Required proof shape","id":"/rules/RG1007/#RG1007-proof-shape"},"/rules/RG4004/#RG4004-proof-shape":{"contents":"No proof obligation: the example demonstrates a compiler-trusting mechanism and is excluded from conforming evidence.\n\n","context":"Regula rule reference\u0009Rule index\u0009RG4004: Teaching examples require authenticated compiler classification","header":"Required proof shape","id":"/rules/RG4004/#RG4004-proof-shape"},"/rules/RG5003/#RG5003-proof-shape":{"contents":"No proof obligation: the rule checks presence. The Intent text is compared with the declaration in review.\n\n","context":"Regula rule reference\u0009Rule index\u0009RG5003: Registered public material declarations require an Intent section","header":"Required proof shape","id":"/rules/RG5003/#RG5003-proof-shape"}});